//-----------------------------------------------------------
// Description: This module selects four intra prediction mode candidates from the component identifier and the texture feature summary generated by the partition engine. Luma candidates are selected from activity, dominant-direction, strong-dominant, primary-direction, and second-direction information. Chroma candidates use the fixed Planar, DC, horizontal, and vertical mode set. The output uses a one-entry ready/valid register.
//-----------------------------------------------------------
`timescale 1ns/1ps

module INTRA_MODE_PRESELECTION #(
  parameter PARA_MODE_WD = 8
)
(
  input                           I_CLK,
  input                           I_RESETN,

  input                           I_VALID,
  output logic                    O_READY,
  input [1:0]                     I_COMPONENT_ID,
  input [1:0]                     I_ACTIVITY,
  input                           I_DOMINANT,
  input                           I_STRONG_DOMINANT,
  input [2:0]                     I_DIRECTION,
  input [2:0]                     I_SECOND_DIRECTION,

  output logic                    O_VALID,
  input                           I_READY,
  output logic [PARA_MODE_WD-1:0] O_CANDIDATE_MODE_0,
  output logic [PARA_MODE_WD-1:0] O_CANDIDATE_MODE_1,
  output logic [PARA_MODE_WD-1:0] O_CANDIDATE_MODE_2,
  output logic [PARA_MODE_WD-1:0] O_CANDIDATE_MODE_3
);

localparam [1:0] PARA_COMPONENT_Y  = 2'd0;
localparam [1:0] PARA_ACTIVITY_LOW = 2'd0;
localparam [1:0] PARA_ACTIVITY_MED = 2'd1;
localparam [1:0] PARA_ACTIVITY_HIGH = 2'd2;

localparam [2:0] PARA_DIRECTION_NONE = 3'd0;
localparam [2:0] PARA_DIRECTION_H    = 3'd1;
localparam [2:0] PARA_DIRECTION_V    = 3'd2;
localparam [2:0] PARA_DIRECTION_DL   = 3'd3;
localparam [2:0] PARA_DIRECTION_DR   = 3'd4;

localparam [PARA_MODE_WD-1:0] PARA_MODE_PLANAR = 0;
localparam [PARA_MODE_WD-1:0] PARA_MODE_DC     = 1;
localparam [PARA_MODE_WD-1:0] PARA_MODE_2      = 2;
localparam [PARA_MODE_WD-1:0] PARA_MODE_17     = 17;
localparam [PARA_MODE_WD-1:0] PARA_MODE_18     = 18;
localparam [PARA_MODE_WD-1:0] PARA_MODE_19     = 19;
localparam [PARA_MODE_WD-1:0] PARA_MODE_33     = 33;
localparam [PARA_MODE_WD-1:0] PARA_MODE_34     = 34;
localparam [PARA_MODE_WD-1:0] PARA_MODE_35     = 35;
localparam [PARA_MODE_WD-1:0] PARA_MODE_49     = 49;
localparam [PARA_MODE_WD-1:0] PARA_MODE_50     = 50;
localparam [PARA_MODE_WD-1:0] PARA_MODE_51     = 51;
localparam [PARA_MODE_WD-1:0] PARA_MODE_66     = 66;

logic w_output_ready;
logic w_primary_direction_valid;
logic w_second_direction_valid;
logic w_activity_valid;
logic [PARA_MODE_WD-1:0] w_primary_anchor_mode;
logic [PARA_MODE_WD-1:0] w_second_anchor_mode;
logic [PARA_MODE_WD-1:0] w_candidate_mode_0;
logic [PARA_MODE_WD-1:0] w_candidate_mode_1;
logic [PARA_MODE_WD-1:0] w_candidate_mode_2;
logic [PARA_MODE_WD-1:0] w_candidate_mode_3;

logic r_valid;
logic [PARA_MODE_WD-1:0] r_candidate_mode_0;
logic [PARA_MODE_WD-1:0] r_candidate_mode_1;
logic [PARA_MODE_WD-1:0] r_candidate_mode_2;
logic [PARA_MODE_WD-1:0] r_candidate_mode_3;

assign w_output_ready = !r_valid || I_READY;
assign O_READY = w_output_ready;

always_comb begin
  w_primary_direction_valid = 1'b1;
  w_primary_anchor_mode = PARA_MODE_PLANAR;

  unique casez (I_DIRECTION)
    PARA_DIRECTION_H:  w_primary_anchor_mode = PARA_MODE_18;
    PARA_DIRECTION_V:  w_primary_anchor_mode = PARA_MODE_50;
    PARA_DIRECTION_DL: w_primary_anchor_mode = PARA_MODE_2;
    PARA_DIRECTION_DR: w_primary_anchor_mode = PARA_MODE_34;
    default: begin
      w_primary_direction_valid = 1'b0;
      w_primary_anchor_mode = PARA_MODE_PLANAR;
    end
  endcase
end

always_comb begin
  w_second_direction_valid = 1'b1;
  w_second_anchor_mode = PARA_MODE_PLANAR;

  unique casez (I_SECOND_DIRECTION)
    PARA_DIRECTION_H:  w_second_anchor_mode = PARA_MODE_18;
    PARA_DIRECTION_V:  w_second_anchor_mode = PARA_MODE_50;
    PARA_DIRECTION_DL: w_second_anchor_mode = PARA_MODE_2;
    PARA_DIRECTION_DR: w_second_anchor_mode = PARA_MODE_34;
    default: begin
      w_second_direction_valid = 1'b0;
      w_second_anchor_mode = PARA_MODE_PLANAR;
    end
  endcase
end

assign w_activity_valid = (I_ACTIVITY == PARA_ACTIVITY_LOW) || (I_ACTIVITY == PARA_ACTIVITY_MED) || (I_ACTIVITY == PARA_ACTIVITY_HIGH);

always_comb begin
  w_candidate_mode_0 = PARA_MODE_PLANAR;
  w_candidate_mode_1 = PARA_MODE_DC;
  w_candidate_mode_2 = PARA_MODE_18;
  w_candidate_mode_3 = PARA_MODE_50;

  if (I_COMPONENT_ID == PARA_COMPONENT_Y) begin
    if (w_activity_valid && (I_ACTIVITY != PARA_ACTIVITY_LOW) && w_primary_direction_valid) begin
      if (I_STRONG_DOMINANT) begin
        unique casez (I_DIRECTION)
          PARA_DIRECTION_H: begin
            w_candidate_mode_0 = PARA_MODE_18;
            w_candidate_mode_1 = PARA_MODE_17;
            w_candidate_mode_2 = PARA_MODE_19;
            w_candidate_mode_3 = PARA_MODE_PLANAR;
          end

          PARA_DIRECTION_V: begin
            w_candidate_mode_0 = PARA_MODE_50;
            w_candidate_mode_1 = PARA_MODE_49;
            w_candidate_mode_2 = PARA_MODE_51;
            w_candidate_mode_3 = PARA_MODE_PLANAR;
          end

          PARA_DIRECTION_DR: begin
            w_candidate_mode_0 = PARA_MODE_34;
            w_candidate_mode_1 = PARA_MODE_33;
            w_candidate_mode_2 = PARA_MODE_35;
            w_candidate_mode_3 = PARA_MODE_PLANAR;
          end

          PARA_DIRECTION_DL: begin
            w_candidate_mode_0 = PARA_MODE_2;
            w_candidate_mode_1 = PARA_MODE_66;
            w_candidate_mode_2 = PARA_MODE_PLANAR;
            w_candidate_mode_3 = PARA_MODE_DC;
          end

          default: begin
            w_candidate_mode_0 = PARA_MODE_PLANAR;
            w_candidate_mode_1 = PARA_MODE_DC;
            w_candidate_mode_2 = PARA_MODE_18;
            w_candidate_mode_3 = PARA_MODE_50;
          end
        endcase
      end
      else if (I_DOMINANT && w_second_direction_valid) begin
        w_candidate_mode_0 = w_primary_anchor_mode;
        w_candidate_mode_1 = w_second_anchor_mode;
        w_candidate_mode_2 = PARA_MODE_PLANAR;
        w_candidate_mode_3 = PARA_MODE_DC;
      end
      else if (!I_DOMINANT && w_second_direction_valid) begin
        w_candidate_mode_0 = PARA_MODE_PLANAR;
        w_candidate_mode_1 = PARA_MODE_DC;
        w_candidate_mode_2 = w_primary_anchor_mode;
        w_candidate_mode_3 = w_second_anchor_mode;
      end
    end
  end
end

always_ff @ (posedge I_CLK, negedge I_RESETN) begin
  if (!I_RESETN)
    r_valid <= 1'b0;
  else if (w_output_ready)
    r_valid <= I_VALID;
end

always_ff @ (posedge I_CLK) begin
  if (w_output_ready && I_VALID) begin
    r_candidate_mode_0 <= w_candidate_mode_0;
    r_candidate_mode_1 <= w_candidate_mode_1;
    r_candidate_mode_2 <= w_candidate_mode_2;
    r_candidate_mode_3 <= w_candidate_mode_3;
  end
end

assign O_VALID = r_valid;
assign O_CANDIDATE_MODE_0 = r_candidate_mode_0;
assign O_CANDIDATE_MODE_1 = r_candidate_mode_1;
assign O_CANDIDATE_MODE_2 = r_candidate_mode_2;
assign O_CANDIDATE_MODE_3 = r_candidate_mode_3;

endmodule: INTRA_MODE_PRESELECTION
